Q: How to unescape HTML entities in python A: <p>Its easier to use a regex to match the name or code number, then do a replacement:<br />
Sample Python using a callback to do the replacement..</p>
<p><a href="https://www.online-python.com/5gIMvwsi6z" rel="nofollow noreferrer">https://www.online-python.com/5gIMvwsi6z</a></p>
<pre><code>import re

ent_names = { 
  'lt' : '&lt;', 'gt' : '&gt;', 'amp' : '&amp;', 'quot' : '&quot;', 'apos' : &quot;'&quot;, 'copy' : '©', 'reg' : '®', 'trade' : '™', 'euro' : '€', 'pound' : '£', 'yen' : '¥', 'sect' : '§', 'deg' : '°', 'micro' : 'µ', 'para' : '¶', 'plusmn' : '±', 'divide' : '÷', 'times' : '×' 
}   

def repl(m):
    t = m.group(3)
    if m.group(1) :
       return chr(int(t,16)) if m.group(2) else chr(int(t))
    return ent_names[t] if t in ent_names else m.group()

test_str = 'Hello &amp;lt; &amp;#x27;  &amp;#165; &amp;#8364; &amp;#39; &amp;unknown; &amp;#62; World'

mod_str = re.sub(r'(?i)(?=&amp;(?:[a-z]+|\#(?:[0-9]+|x[0-9a-f]+));)&amp;(\#)?(x)?([0-9a-z]+);', repl, test_str )

print ( test_str + &quot;\n&quot; + mod_str + &quot;\n&quot; )
</code></pre>
